WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) INSERT INTO executivos (nome, email, cargo) SELECT TRIM(:nome), lower(TRIM(:email)), COALESCE(NULLIF(TRIM(:cargo), ''), 'Executivo comercial') FROM eu WHERE eu.admin AND TRIM(:nome) <> '' AND lower(TRIM(:email)) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio') ON CONFLICT (nome) DO UPDATE SET email = EXCLUDED.email, cargo = EXCLUDED.cargo, ativo = true RETURNING id, nome, email, cargo, ativo
